二分图如果一个图的顶点可以分为两个集合，图的所有边的两个顶点分属两个集合，则该图为“二分图” (Bipartite Graph)
二分图的最大匹配匹配：在图论中，一个“匹配”（matching）是一个边的集合，其中任意两条边都没有公共顶点一个图所有匹配中，所含匹配边数最多的匹配，称为这个图的最大匹配。二分图的应用中，求最大匹配数是最常见的，其他的很多问题都可以转化为求最大匹配数（如最小覆盖数）
DFS实现匈牙利算法伪代码从一侧点出发，通过相连的线段到达未与其他点匹配的另一侧点，最大匹配数即为符合上述要求的点的个数通过dfs算法实现，从左侧点出发，尝试连接右侧点
int hungary()&#123;
    int res=0;//res初始化，用来记录匹配最大匹配数
    memset(linker,-1,sizeof(linker));//linker[]用来记录目前右边点的连接情况
    for(int l=0;l &lt; lN;l++)
    &#123;
        memset(used,0,sizeof(used));//对于该点，初始时未开始与左侧各点连接
        if(dfs(u))res++;//通过dfs判定上述要求能否成功
    &#125;//lN为左侧点的个数，l为正在尝试连接的点的序号
    return res;//返回最大匹配数
&#125;
bool dfs(int l)&#123;
    for(int r=0;r &lt; rN;r++)&#123;
        if(g[l][r] &amp;&amp; !used[r])&#123;
            used[r]=1;
            if(linker[r]==-1 || dfs(linker[r]))&#123;
                linker[r]=u;
                return 1;
            &#125;
        &#125;
    &#125;
    return 0;
    /*r为右边点序号，rN为右边点个数，g[][]记录左右两侧点的连接情况
    对于未被尝试连接过的点，如果该点未与其他点连接则直接相连(linker[r]==-1)，将右侧点的连接对象标记为该点
    若已有左侧点p与其相连，先将该右侧点标记为不可再连，再去考虑点p能否与其他点相连(dfs(linker[r]))
    以此类推，最后找到一个左侧点与右侧未与其他相连的点连接，则返回真，匹配数加一，否则匹配数不变*/
&#125;

二分图匹配匈牙利算法dfs实现的优劣优点：

算法的邻接矩阵适用于稠密矩阵
算法实现简洁，易于理解学习

缺点：

时间复杂度O(VE)，V为顶点数，E为边数，对于二分图匹配，理论上存在更快的算法——Hopcrott-Karp算法，该算法利用BFS同时寻找多条互补相交的最短增广路，并在一次迭代中全部用于增广。时间复杂度达到O(sqrt(V)*E),但在规模不大的稀疏图中，由于常数因子较小且易于实现，仍然常用

匈牙利算法的应用示例（最大匹配数及其变式）求最大匹配数广泛应用于任务分配、网络流优化、稳定婚姻问题等领域
最小顶点覆盖求取最少的顶点，使每条线至少和其中一个顶点关联二分图最小顶点覆盖&#x3D;二分图最大匹配数(koning 定理)
最大独立数选取最多的点，使任意所选两点均不相连最大独立数&#x3D;最大匹配数
DAG图的最小路径覆盖对于一个 DAG（有向无环图），选取最少条路径，使得每个顶点属于且仅属于一条路径。路径长可以为 0（即单个点）最小路径覆盖数 &#x3D; 顶点数 - 最大匹配数
总结基于DFS算法实现匈牙利算法，本质上还是穷举所有可能，如果DFS学习到位还是非常好理解的

平衡树//数据结构初始化
struct node&#123;
    int val,rnk,lc,rc,size;//值，优先级，左右子节点，子树大小
&#125;tree[N];
int tot,root;//总结点数和根节点数

//节点管理
void update(int k)&#123;
    tree[k].size=tree[tree[k].lc].size+tree[tree[k].rc].size+1;
    return;
&#125;
int add_node(int val)&#123;
    tree[++tot].size=1;
    tree[tot].val=0;
    tree[tot].lc=tree[tot].rc=0;
    tree[tot].rnk=rand();
    return tot;
&#125;

void split(int k,int &amp;a,int &amp;b,int val)&#123;
    if(k==0)&#123;
        a=b=0;
        return ;
    &#125;
    if(tree[k].val&lt;=val)&#123;
        a=k;
        split(tree[k].rc,tree[k].rc,b,val);
    &#125;
    else &#123;
        b=k;
        split(tree[k].lc,a,tree[k].lc,val);
    &#125;
    update(k);
&#125;
//给定一棵平衡树 ，按照某个权值val，分裂成平衡树a和b，且a树所有点的权值不超过val，b树的所有点权大于val。

void merge(int &amp;k ,int a,int b)&#123;
    if(a==0||b==0)&#123;
        k=a+b;
        return;
    &#125;
    if(tree[a].rnk&lt;tree[b].rnk)&#123;
        k=a;
        merge(tree[a].rc,tree[a].rc,b);
    &#125;
    else &#123;
        k=b;
        merge(tree[b].lc,a,tree[b].lc);
    &#125;
    update(k);
&#125;

void insert(int &amp;k ,int val)&#123;
    int a=0,b=0,cur=add_node(val);
    split(k,a,b,val);
    merge(a,a,cur);
    merge(k,a,b);
    return;
&#125;
void del(int &amp;k,int val)&#123;
    int a=0,b=0,z=0;
    split(k,a,b,val);
    split(a,a,z,val-1);
    merge(z,tree[z].lc,tree[z].rc);
    merge(a,a,z);
    merge(k,a,b);
    return;
&#125;

int find_num(int k,int x)&#123;
    while(tree[tree[k].lc]+1!=x)&#123;
        if(tree[tree[k].lc].size&gt;=x)&#123;
            k=tree[k].lc;
        &#125;
        else &#123;
            x-=tree[tree[k].lc].size;
            k=tree[k].rc;
        &#125;
    &#125;
    return tree[k].val;
&#125;
//找到树上第x小的数

int find_rank(int &amp;k,int val)&#123;
    int a=0,b=0;
    split(k,a,b,val-1);
    int temp=tree[a].size+1;
    merge(k,a,b);
    return;
&#125;
//查询val的排名

int prev(int &amp;k,int val)&#123;
    int a=0,b=0;
    split(k,a,b,val-1);
    int temp=find_num(a,tree[a].size);
    merge(k,a,b);
    return temp;
&#125;
//查询比val小的最大值

int suf(int &amp;k,int val)&#123;
    int a=0,b=0;
    split(k,a,b,val);
    int temp=find_num(b,1);
    merge(k,a,b);
    return temp;
&#125;

文艺平衡树支持区间操作的平衡树。如区间反转，区间求和&#x2F;最值，区间赋值
//初始化
struct node&#123;
    int size,lc,rc,rnk,val;
    bool rev;
&#125;tree[N];

void pushdown(int k)&#123;
    if(tree[k].rev)&#123;
        swap(tree[k].lc,tree[k].rc);
        tree[tree[k].lc].rev^=1;
        tree[tree[k].rc].rev^=1;
        tree[k].rev=0;
    &#125;
    return ;
&#125;
//lazy tag方式延迟执行

void split_sz(int k,int &amp;a,int &amp;b,int sz)&#123;
    if(k==0)&#123;
        a=b=0;
        return;
    &#125;
    pushdown(k);
    if(tree[tree[k].lc].size+1&lt;=sz)&#123;
        a=k;
        split(tree[k].rc,tree[k].rc,b,sz-tree[tree[k].rc].size-1);
    &#125;
    else &#123;
        n=k;
        split(tree[k].lc,a,tree[k].lc,sz);
    &#125;
&#125;
//分出树的前sz个节点

void reverse(int l,int r)&#123;
    int a=0,b=0,c=0;
    split(root,a,b,l-1);
    split(b,b,c,r-l+1);
    tree[b].rev^=1;
    merge(a,a,b);
    merge(root,a,c);
&#125;
//将l到r的区间反转
